from collections import UserList

def _t():
    l = [0, 1, 2, 3, 4]
    u = UserList(l)
    assert isinstance(u[:], u.__class__), ('assertIsInstance', u[:], u.__class__)
    assert u[:] == u, ('assertEqual', u[:], u)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
